from typing import Callable, Optional

@dataclass(frozen=True)
class Sentence:
    kind: str
    n: int = 0
    k: int = 0
    pred: Optional[Callable[[int], "Sentence"]] = None

def atom(n: int) -> Sentence: return Sentence("atom", n=n)
def ex(p: Callable[[int], Sentence]) -> Sentence: return Sentence("ex", pred=p)

class Model:
    def __init__(self, atom_true: Callable[[int], bool], bound: int = 64) -> None:
        self.atom_true, self.bound = atom_true, bound
    def c_true(self, s: Sentence) -> bool:
        if s.kind == "atom": return self.atom_true(s.n)
        if s.kind == "ex":
            return any(self.c_true(s.pred(n)) for n in range(self.bound))
        return False
    def c_prov(self, s: Sentence) -> bool:
        return s.kind == "ex" and self.c_true(s)   # never proves an atom

m = Model(atom_true=lambda _n: True)
print("proves existence :", m.c_prov(ex(atom)))
print("proves instance  :", any(m.c_prov(atom(n)) for n in range(16)))
true_but_unprovable = [n for n in range(8)
                       if m.c_true(atom(n)) and not m.c_prov(atom(n))]
print("true-but-unprovable witnesses:", true_but_unprovable)

