from dataclasses import dataclass
from typing import Callable, Optional

@dataclass(frozen=True)
class Sentence:
    kind: str
    n: int = 0
    k: int = 0
    pred: Optional[Callable[[int], "Sentence"]] = None

def c_true(s: Sentence, atom_true: Callable[[int], bool], bound: int = 64) -> bool:
    if s.kind == "atom":
        return atom_true(s.n)
    if s.kind == "bot":
        return False
    if s.kind == "ex":
        assert s.pred is not None
        return any(c_true(s.pred(n), atom_true, bound) for n in range(bound))
    if s.kind == "atLeast":
        assert s.pred is not None
        w = [n for n in range(bound) if c_true(s.pred(n), atom_true, bound)]
        return len(w) >= s.k
    raise ValueError(s.kind)

def c_prov(s: Sentence, atom_true: Callable[[int], bool], bound: int = 64) -> bool:
    if s.kind in ("ex", "atLeast"):
        return c_true(s, atom_true, bound)
    return False

from typing import Callable, Optional
from dataclasses import dataclass

@dataclass(frozen=True)
class Sentence:
    kind: str
    n: int = 0
    k: int = 0
    pred: Optional[Callable[[int], "Sentence"]] = None

def atom(n: int) -> Sentence: return Sentence("atom", n=n)
def at_least(k: int, p: Callable[[int], Sentence]) -> Sentence:
    return Sentence("atLeast", k=k, pred=p)

def darkness_level(pred: Callable[[int], Sentence],
                   atom_true: Callable[[int], bool],
                   bound: int = 64) -> int:
    # not dark if any instance is provable (atoms are never provable here)
    def c_true(s: Sentence) -> bool:
        if s.kind == "atom": return atom_true(s.n)
        if s.kind == "atLeast":
            return sum(1 for n in range(bound) if c_true(pred(n))) >= s.k
        return False
    k = 0
    while c_true(at_least(k + 1, pred)):
        k += 1
    return k

from typing import Callable, List

def diagonal_disagreement(decider: Callable[[int, int], bool],
                          num_statements: int = 16) -> List[int]:
    """Return indices where a diagonal statement is forced to disagree with D."""
    def diagonal_instance(i: int) -> bool:
        return not decider(i, i)          # negate the decider's diagonal guess
    return [i for i in range(num_statements)
            if diagonal_instance(i) != decider(i, i)]   # always all of them

if __name__ == "__main__":
    D = lambda i, n: (i * 7 + n) % 2 == 0
    bad = diagonal_disagreement(D)
    print(f"decider wrong on {len(bad)} diagonal entries -> no uniform decider")
